//go:build amd64

package bitset

// AVX2 kernels, 64 bools and one word per iteration; they return the words
// converted. Generated by go-asmgen (bitset_amd64_gen.go), in bitset_amd64.s.
func packBoolsKernel(words []uint64, bools []byte) (done int)
func unpackBoolsKernel(words []uint64, bools []byte) (done int)

func packBools(dst []uint64, src []byte) int {
	if hasAVX2 {
		return packBoolsKernel(dst, src)
	}
	return 0
}

func unpackBools(dst []byte, src []uint64) int {
	if hasAVX2 {
		return unpackBoolsKernel(src, dst)
	}
	return 0
}
